startDecorations({ frame(client, frame) {
if (!frame.server) return false;
frame.top.size = 30; frame.right.size = 20; frame.bottom.size = 40; frame.left.size = 10;
frame.left.hideWhen = (c) => c.maximised;
} });
globalThis.inset = () => { const i = gnoblin.clients.at(0).frameInset; return [i.top, i.right, i.bottom, i.left]; };
globalThis.bounds = () => { const c = gnoblin.clients.at(0); return [c.x, c.y, c.width, c.height]; };
